/* Lot 108: horizontal box scrolling in the engine (generated by scripts/lot108_gen.py; expectations from scripts/lot108_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "webeng.h"
#include "wf_geom.h"

int we_geom(const we_doc_t *d, int node, wf_geom_box_t *g);

static we_doc_t g_doc;
static we_forms_t g_forms;
static char g_o[2048];
static int g_box;

static int node_of(const char *id) {
    int i;
    for (i = 0; i < (int)g_doc.nnodes; i++)
        if (!strcmp(g_doc.nodes[i].id, id)) return i;
    return -1;
}

/* the page with forms attached, laid out at 640 x 480; g_box is #o */
static void lay(const char *html) {
    we_forms_init(&g_forms);
    we_set_forms(&g_doc, &g_forms);
    TEST_ASSERT_EQUAL(0, we_parse(&g_doc, html, (int)strlen(html)));
    TEST_ASSERT_EQUAL(0, we_style(&g_doc));
    TEST_ASSERT_EQUAL(0, we_layout_viewport(&g_doc, 640, 480));
    g_box = node_of("o");
    TEST_ASSERT_TRUE(g_box > 0);
}

/* the box of #o: x y w h, the offset along x and y */
static const char *box(void) {
    const we_node_t *n = &g_doc.nodes[g_box];
    snprintf(g_o, sizeof(g_o), "%d %d %d %d %d %d", n->x, n->y, n->w, n->h, n->box_scroll_x, n->box_scroll_y);
    return g_o;
}

/* the geometry of #o along x: svx x_vp x_sc x_rg */
static const char *gx(void) {
    wf_geom_box_t g;
    memset(&g, 0, sizeof(g));
    if (we_geom(&g_doc, g_box, &g) != 0) return "NO GEOM";
    snprintf(g_o, sizeof(g_o), "%d %d %d %d", g.svx, g.x_vp, g.x_sc, g.x_rg);
    return g_o;
}

/* row id: x, then its geometry along the inline axis: i_off i_size vp_i
 * sc_i rg_i */
static const char *row(const char *id) {
    wf_geom_box_t g;
    int k = node_of(id);
    memset(&g, 0, sizeof(g));
    if (k <= 0 || we_geom(&g_doc, k, &g) != 0) return "NO ROW";
    snprintf(g_o, sizeof(g_o), "%d | %d %d %d %d %d", g_doc.nodes[k].x, g.i_off, g.i_size, g.vp_i, g.sc_i, g.rg_i);
    return g_o;
}

/* the scrollbar rectangles of #o in paint order: x,y,wxh,colour */
static const char *bars(void) {
    int i, n = 0;
    g_o[0] = 0;
    for (i = 0; i < (int)g_doc.nitems; i++) {
        const os_fb_web_item_t *it = &g_doc.items[i];
        if (g_doc.item_owner[i] != g_box || it->kind != OS_FB_WEB_RECT) continue;
        if (it->color != 0xDDDDDD && it->color != 0x888888) continue;
        n += snprintf(g_o + n, sizeof(g_o) - (size_t)n, "%s%d,%d,%dx%d,%06x", n ? " " : "", it->x, it->y, it->w, it->h,
                      (unsigned)it->color);
    }
    return g_o;
}

/* a click at x, y, then the page laid out again */
static int click(int x, int y) {
    int r = we_box_scroll_click(&g_doc, x, y);
    if (we_layout_viewport(&g_doc, 640, 480) != 0) return -99;
    return r;
}

